<script setup lang="ts">
import DataTable from '../../components/DataTable.vue'
type Row = Record<string, string>
defineProps<{ rows: Row[]; selectedId: string; total: number; currentPage: number; loading: boolean; error: string; busy: boolean; role?: string }>()
const emit = defineEmits<{ reload: []; select: [id: string]; view: [id: string]; run: [id: string]; page: [page: number] }>()
const search = defineModel<string>('search', { required: true })
</script>

<template>
<article class="panel matching-batch-panel"><div class="matching-batch-heading"><div><h2>Daftar batch</h2><p>Pilih batch untuk melihat hasil. Jalankan matching pada batch berstatus READY.</p></div><input v-model="search" class="form-control matching-batch-search" aria-label="Cari batch" placeholder="Cari nomor batch atau rekening" /></div><p v-if="loading" class="table-state">Memuat batch…</p><p v-else-if="error" class="table-state error-state">{{ error }} <button class="button secondary" @click="emit('reload')">Coba lagi</button></p><DataTable v-else :columns="[{ key: 'batch', label: 'No. Batch' }, { key: 'account', label: 'Rekening' }, { key: 'period', label: 'Periode' }, { key: 'status', label: 'Status' }]" :rows="rows" link-key="batch" @open="emit('select', $event.id)"><template #actions="{ row }"><div class="matching-row-actions"><button class="matching-view-button" type="button" :aria-label="`Lihat hasil ${row.batch}`" @click="emit('view', row.id)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.5"/></svg>{{ selectedId === row.id ? 'Dipilih' : 'Lihat hasil' }}</button><button v-if="role === 'OPERATOR' && row.status === 'READY'" class="matching-run-button" type="button" :disabled="busy" :aria-label="`Jalankan matching batch ${row.batch}`" @click="emit('run', row.id)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 11 7-11 7V5Z"/></svg>Jalankan Matching</button></div></template></DataTable><div class="table-footer"><span>{{ total }} batch ditemukan</span><div><button :disabled="currentPage <= 1 || loading" @click="emit('page', currentPage - 1)">‹</button><button class="current-page">{{ currentPage }} / {{ Math.max(1, Math.ceil(total / 25)) }}</button><button :disabled="currentPage >= Math.ceil(total / 25) || loading" @click="emit('page', currentPage + 1)">›</button></div></div></article>
</template>
